{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "상업지역 등 조례가 부대시설 종류를 제한하는 지역의 노외주차장에서, 제한 목록에 종교시설이 없다는 이유만으로 이미 허용된 용도로 사용 중인 종교시설 부분에도 제한이 적용되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "상업지역·준주거지역 등 주차장설치제한지역에 설치되는 노외주차장의 부대시설 종류는 제16조제1항에도 불구하고 제1종·제2종 근린생활시설, 업무시설(오피스텔 제외), 운동시설로 제한되나, 그 제한 목록에 종교시설이 포함되어 있지 않더라도 기존에 허용된 용도로 사용되고 있는 부분에는 이 제한을 적용하지 아니한다.",
          "b_ids": "주차장:제16조제2항, 주차장:제16조제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
